const Q=s=>document.querySelector(s),safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),cash=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const key='ledger-lane-classroom-v1';let data;try{data=JSON.parse(localStorage.getItem(key));}catch{}data||={profile:null,assignments:[],runs:{}};let role='home',page='assignments',active=null,record=null,teacherDraft=null,teacherTab='builder',notice='',entryRows=[{account:'',debit:'',credit:''},{account:'',debit:'',credit:''}];
const icons=Object.fromEntries(Object.entries(Lessons.businesses).map(([k,v])=>[k,v.icon])),equipmentNames=Object.fromEntries(Object.entries(Lessons.businesses).map(([k,v])=>[k,v.equipment]));let designDraft=null,reviewPlan=0;
function persist(){try{localStorage.setItem(key,JSON.stringify(data));}catch{notice='Browser storage is unavailable. Keep this tab open and export work before closing.';}}
function makeAssignment(topic,index=0){const t=Lessons.topics[topic];return {version:1,id:'demo-'+topic,title:['A home for your business','A customer buys on account','Equipment that lasts','Opening the doors'][index]||t.name,topic,course:'Introduction to Financial Accounting',instructions:t.goal,year:2026,month:9,support:'guided',notes:'',published:true,origin:'Example assignment'};}
if(!data.assignments.length){data.assignments=[Lessons.generateAssignment('Prepaid rent and insurance. Supplies are assets until consumed; use a month-end physical count.',{id:'practice-opening',title:'Find your footing',depth:'standard'}),Lessons.generateAssignment('Credit sales on account and customer collections. Unearned revenue for customer deposits. Accrue wages earned by staff before payday.',{id:'practice-customers',title:'Customers, commitments & payday',month:10})].map(a=>({...a,published:true,origin:'Practice episode'}));persist();}
function run(){return data.runs[active];}function assignment(){return run()?.assignment||data.assignments.find(a=>a.id===active);}function month(a){return new Date(a.year,a.month-1,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});}function header(){return `<header><a href="#" class="brand" id="brand-home"><span>▥</span> ledger lane</a><div class="header-tools"><button class="quiet" id="help">How it works</button><button class="secondary" id="full">Full screen</button><button class="quiet" id="role-home">Home</button></div></header>`;}
function shell(content){Q('#classroom').innerHTML='<main class="shell">'+header()+content+(notice?`<div class="message" role="status">${safe(notice)}</div>`:'')+'<p class="foot classroom-foot">Classroom prototype · saved on this browser · assignments can be shared as files · no authenticated accounts or shared gradebook yet</p></main><dialog id="lesson-dialog"></dialog>';Q('#role-home').onclick=()=>{role='home';notice='';render();};Q('#brand-home').onclick=e=>{e.preventDefault();role='home';render();};Q('#full').onclick=async()=>{try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen();}catch{notice='Use F11 on Windows or Control + Command + F on Mac for full screen.';render();}};Q('#help').onclick=help;}
function render(){if(role==='home'){shell(`<section class="welcome-site"><div class="welcome-copy"><span class="welcome-label">LEDGER LANE · ACCOUNTING EDUCATION</span><h1>Give accounting<br>a business context.</h1><p>Students build a business. Professors assign the work. Every transaction becomes a chance to understand the accounts.</p><div class="welcome-actions"><button id="student">Explore the student experience</button><button id="professor" class="secondary">Explore instructor tools</button></div><p class="welcome-note">Already have a class account? Sign in above to continue.</p></div><div class="welcome-product"><div class="product-bar"><span>Ledger Lane</span><span>Student workspace</span></div><div class="product-business"><span class="business-monogram">TC</span><div><strong>Tommy’s Coffee</strong><small>September · Accounting classroom</small></div></div><div class="product-tabs"><span class="active">Assignments</span><span>General ledger</span><span>Business profile</span></div><div class="product-assignment"><span class="welcome-label">CURRENT ASSIGNMENT</span><h3>A new home for your business</h3><p>Review the lease, record the payment, and account for the coverage used.</p><div class="product-status"><span>Source records</span><strong>4 documents</strong></div><div class="product-status"><span>Bookkeeping</span><strong>In progress</strong></div></div><div class="product-document"><span>Oak Street Property Management</span><strong>Commercial rental receipt</strong><small>Coverage period · September–November</small><div><span>Payment received</span><strong>$1,800.00</strong></div></div></div></section><section class="welcome-features"><div><span>01</span><h2>A business of their own</h2><p>Students choose an identity that stays with them throughout the course.</p></div><div><span>02</span><h2>Assignments from your teaching</h2><p>Start with course notes, review the scenario and answer key, then publish to your class.</p></div><div><span>03</span><h2>Accounting they actually prepare</h2><p>Students read source records, write dated entries, and explain the results through their accounts.</p></div></section><div class="welcome-bottom"><span>Designed for introductory financial accounting.</span><a href="capstone.html">View the comprehensive simulation →</a></div>`);Q('#student').onclick=()=>{role='student';page='assignments';render();};Q('#professor').onclick=()=>{role='professor';render();};return;}
if(role==='professor'){renderProfessor();return;}if(!data.profile){profilePage();return;}renderStudent();}
function profilePage(){designDraft={name:'',type:'Coffee shop',color:'sage',style:Lessons.styles[0],district:Lessons.districts[0],...designDraft};shell(`<section class="designer-heading"><div class="tag">YOUR SEMESTER STARTS HERE</div><h1>A business that’s yours.</h1><p>Choose what you do, design your place, and give it a personality. This business stays with you all semester.</p></section>${designer('profile-form')}`);wireDesigner('profile-form',false);Q('#profile-form').onsubmit=e=>{e.preventDefault();try{data.profile=Lessons.normalizeBusiness(readBusinessForm(e.target));designDraft=null;persist();render();}catch(error){notice=error.message;render();}};}
function readBusinessForm(form){const f=Object.fromEntries(new FormData(form));return {name:f.name,type:f.type,color:f.color,style:f.style,district:f.district,specialty:f.specialty,logo:f.logo,tagline:f.tagline};}
function designer(id,editing=false){const p=designDraft||data.profile,biz=Lessons.businesses[p.type];return `<form id="${id}" class="business-designer"><section><div class="tag">01 · FIND YOUR THING</div><h2>What will you build?</h2><div class="business-picker">${Object.entries(Lessons.businesses).map(([type,b])=>`<label class="business-tile ${p.type===type?'chosen':''}"><input type="radio" name="type" value="${safe(type)}" ${p.type===type?'checked':''} ${editing?'disabled':''}><span class="business-icon">${b.icon}</span><strong>${safe(type)}</strong><small>${safe(b.description)}</small></label>`).join('')}</div>${editing?`<input type="hidden" name="type" value="${safe(p.type)}"><p class="foot">Your business type stays with completed assignment records.</p>`:''}</section><section class="card designer-preview"><div id="design-shop">${shop(p)}</div><div class="tag">02 · MAKE IT YOURS</div><label class="field">Business name<input id="business-name" name="name" maxlength="45" required placeholder="Tommy’s Coffee" value="${safe(p.name)}"></label><label class="field">A line for your sign<input name="tagline" maxlength="70" placeholder="Good mornings start here" value="${safe(p.tagline||'')}"></label><label class="field">Your specialty<select name="specialty">${biz.products.map(x=>`<option ${x===p.specialty?'selected':''}>${safe(x)}</option>`).join('')}</select></label><div class="form-pair"><label class="field">Storefront<select name="style">${Lessons.styles.map(x=>`<option ${x===p.style?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Neighborhood<select name="district">${Lessons.districts.map(x=>`<option ${x===p.district?'selected':''}>${x}</option>`).join('')}</select></label></div><fieldset class="palette"><legend>Brand color</legend>${Object.entries(Lessons.colors).map(([color,hex])=>`<label style="--swatch:${hex}" title="${color}"><input type="radio" name="color" value="${color}" ${color===p.color?'checked':''}><span></span><small>${color}</small></label>`).join('')}</fieldset><label class="field">Sign symbol<select name="logo">${[biz.icon,'✦','●','❧','◇'].map(x=>`<option ${x===p.logo?'selected':''}>${x}</option>`).join('')}</select></label><p class="foot">Your design is personal. Accounting assignments start with their own verified balances.</p><button ${id==='profile-form'?'data-cloud-submit':''}>${editing?'Save my business':'Open my business'} →</button></section></form>`;}
function wireDesigner(id,editing){const form=Q('#'+id);form.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{const v=readBusinessForm(form);const typeChanged=v.type!==designDraft.type;if(typeChanged){v.specialty=Lessons.businesses[v.type].products[0];v.logo=Lessons.businesses[v.type].icon;}designDraft=v;form.querySelectorAll('.business-tile').forEach(t=>t.classList.toggle('chosen',t.querySelector('input').value===v.type));const specialty=form.querySelector('[name=specialty]'),logo=form.querySelector('[name=logo]');if(typeChanged||!Lessons.businesses[v.type].products.includes(specialty.value)){specialty.innerHTML=Lessons.businesses[v.type].products.map(x=>`<option>${safe(x)}</option>`).join('');}if(typeChanged||![Lessons.businesses[v.type].icon,'✦','●','❧','◇'].includes(logo.value)){logo.innerHTML=[Lessons.businesses[v.type].icon,'✦','●','❧','◇'].map(x=>`<option>${x}</option>`).join('');}Q('#design-shop').innerHTML=shop(designDraft);}));}

function shop(p=data.profile){const b=Lessons.businesses[p.type]||Lessons.businesses['Coffee shop'],style=p.style||Lessons.styles[0];return `<div class="class-shop ${safe(p.color)} ${style==='Modern studio'?'modern':style==='Garden storefront'?'garden':''}" style="--brand:${Lessons.colors[p.color]||Lessons.colors.sage}"><div class="district-line">${safe(p.district||Lessons.districts[0])} · ${safe(p.type)}</div><div class="shop-sign"><span>${safe(p.logo||b.icon)}</span> ${safe(p.name||'Your business')}<small>${safe(p.tagline||p.specialty||b.products[0])}</small></div><div class="class-awning"></div><div class="class-windows"><span>${b.icon}</span><span class="shop-door">${run()?.completed?'MONTH CLOSED':'OPEN'}</span><span>${safe(p.logo||b.icon)}</span></div><div class="shop-sidewalk"></div></div>`;}

function studentIntro(){return `<div class="intro"><div><div class="tag">${safe(data.profile.type)} · BUSINESS CLASSROOM</div><h1>${safe(data.profile.name)}</h1><p>Same business. A fresh accounting story for every assignment.</p></div><button id="import" class="secondary">Import assignment</button></div><nav class="tabs"><button data-page="assignments" class="${page==='assignments'?'selected':''}">Assignments</button><button data-page="ledger" class="${page==='ledger'?'selected':''}">General ledger</button><button data-page="portfolio" class="${page==='portfolio'?'selected':''}">Learning portfolio</button><button data-page="profile" class="${page==='profile'?'selected':''}">Business profile</button></nav>`;}
function studentNav(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;active=null;notice='';render();});Q('#import').onclick=importAssignment;}
function renderStudent(){let content='';if(page==='profile')content=`<div class="role-grid"><section class="card">${shop()}</section><section class="card"><h2>Your business identity</h2><p><strong>${safe(data.profile.name)}</strong><br>${safe(data.profile.type)}</p><p>Business identity carries across assignments. Balances, transactions and mistakes do not. Each assignment is a separate classroom scenario.</p><button id="edit-profile" class="secondary">Redesign my business</button></section></div>`;else if(page==='ledger')content=ledgerPage();else if(page==='portfolio')content=portfolio();else if(active)content=assignmentPage();else content=`<div class="assignment-layout"><section class="card business-summary">${shop()}<h3>A business worth understanding.</h3><p>Select a lesson or import an assignment from your professor. You will choose a business action, read the documents, and account for the result.</p><div class="message">Example assignments are ready to try. Your professor can replace these with course-specific assignments.</div></section><div class="assignment-list">${data.assignments.filter(a=>a.published).map(a=>{const r=data.runs[a.id],s=r?Lessons.grade(r):null;return `<section class="card assignment-card"><div class="tag">${safe(a.origin||a.course)} · ${Lessons.topic(a).name}</div><h2>${safe(a.title)}</h2><p>${safe(a.instructions)}</p><div class="assignment-meta"><span>${month(a)}</span><span>${a.version===3?'Business plan · '+Lessons.expected(a,{plan:0},data.profile).events.length+' records':a.version===2?a.concepts.length+' decisions · '+Lessons.expected(a,Lessons.defaultEpisodeChoice(a),data.profile).events.length+' records':'One decision · two records'}</span><span>${r?.completed?'Completed':r?'In progress':'Not started'}</span>${a.version===3?'<span>Created from course notes</span>':a.version===2?`<span>${safe(a.concepts.map(id=>Lessons.concepts[id].name).join(' · '))}</span>`:''}</div><button data-open="${safe(a.id)}">${r?.completed?'Review assignment':r?'Continue assignment':'Start assignment'} →</button></section>`;}).join('')}</div></div>`;
shell(studentIntro()+content);studentNav();if(page==='ledger'&&Q('#open-ledger'))Q('#open-ledger').onclick=()=>{const old=active;active=Q('#ledger-episode').value;tAccounts();active=old;};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{active=b.dataset.open;record=null;notice='';render();});if(page==='profile')Q('#edit-profile').onclick=editProfile;if(page==='portfolio'){Q('#export-portfolio').onclick=()=>download('ledger-lane-portfolio.json',{version:1,profile:data.profile,runs:data.runs,note:'Local student-controlled work, not an authenticated grade record.'});return;}if(active)wireAssignment();}
function portfolio(){const rows=data.assignments.filter(a=>data.runs[a.id]);return `<section class="card portfolio-card"><div class="tag">PRACTICE, FEEDBACK, AND PROGRESS</div><h2>Your learning portfolio</h2><p>Journal entries: 80 points. Financial effects: 15 points. One concept check: 5 points. First-attempt scores remain when you correct your work.</p><table><thead><tr><th>Assignment</th><th>Journal</th><th>Effects</th><th>Prediction</th><th>Status</th></tr></thead><tbody>${rows.map(a=>{const r=data.runs[a.id],s=Lessons.grade(r);return `<tr><td>${safe(a.title)}</td><td>${s.journal}/80</td><td>${s.effects}/15</td><td>${s.prediction}/5</td><td>${r.completed?'Completed':'In progress'}</td></tr>`;}).join('')||'<tr><td colspan="5">Start an assignment to begin your portfolio.</td></tr>'}</tbody></table><button id="export-portfolio">Download portfolio</button><p class="foot">Practice exports are copies of work on this browser. Sign in to submit to your professor’s gradebook.</p></section>`;}
function editProfile(){designDraft={...data.profile};const d=Q('#lesson-dialog');d.innerHTML=`<h2>Your business, your style.</h2>${designer('edit-profile-form',true)}<button class="quiet" id="cancel-design">Cancel</button>`;d.showModal();wireDesigner('edit-profile-form',true);Q('#cancel-design').onclick=()=>{designDraft=null;d.close();};Q('#edit-profile-form').onsubmit=e=>{e.preventDefault();data.profile=Lessons.normalizeBusiness(readBusinessForm(e.target));designDraft=null;persist();d.close();render();};}

function choiceForm(a){if(a.version===3)return generatedChoiceForm(a);if(a.version===2)return episodeChoiceForm(a);let fields='';if(a.topic==='prepaid')fields=`<label class="field">Location<select name="location"><option value="0">Quiet side street · $150/month</option><option value="1">Neighborhood main street · $250/month</option><option value="2">Town center · $400/month</option></select></label><label class="field">Pay in advance for<select name="months"><option value="1">One month</option><option value="3" selected>Three months</option><option value="6">Six months</option></select></label><p>The payment purchases coverage beginning on the first day of the assignment month. At month-end, one month has been used. Other operating transactions are excluded from this lesson.</p>`;if(a.topic==='receivables')fields=`<label class="field">Customer order<select name="order"><option value="0">Small order · $400</option><option value="1">Medium order · $700</option><option value="2">Large order · $1,000</option></select></label><label class="field">Customer payment arrangement<select name="collection"><option value="0">Collect 25% this month</option><option value="1" selected>Collect 50% this month</option><option value="2">Collect 100% this month</option></select></label><p>You deliver the order on credit, then collect the agreed portion later in the month. Supplies and other expenses are outside this focused lesson.</p>`;if(a.topic==='equipment')fields=`<label class="field">Equipment package<select name="level">${equipmentNames[data.profile.type].map((x,i)=>`<option value="${i}">${safe(x)} · ${cash([600,1200,1800][i])}</option>`).join('')}</select></label><label class="field">Estimated useful life<select name="life"><option value="0">3 years</option><option value="1" selected>5 years</option><option value="2">6 years</option></select></label><p>Equipment is placed in service on the first day. Use straight-line depreciation, zero residual value, and one full month of use. The estimate is a classroom choice; actual estimates require evidence.</p>`;if(a.topic==='capital')fields=`<label class="field">Owner contribution<select name="investment"><option value="0">$3,000</option><option value="1" selected>$5,000</option><option value="2">$7,000</option></select></label><label class="field">Advertising package<select name="ad"><option value="0">Local listing · $60</option><option value="1">Neighborhood promotion · $120</option><option value="2">Opening campaign · $200</option></select></label><p>The owner funds the business, then you pay for advertising delivered during the month. No sales occur in this focused episode.</p>`;return `<section class="card"><div class="tag">1 · MAKE THE BUSINESS CHOICE</div><h2>What will ${safe(data.profile.name)} do?</h2><form id="business-choice">${fields}<div class="message" id="choice-preview"></div><button>Confirm business decision →</button></form></section>`;}
function assignmentPage(){const a=assignment(),r=run();if(!r)return `<button class="quiet" id="back-assignments">← All assignments</button><div class="lesson-heading"><div class="tag">${Lessons.topic(a).name} · ${month(a)}</div><h2>${safe(a.title)}</h2><p>${safe(a.instructions)}</p><div class="message">Independent scenario · ${a.version===3?'Opening balances are supplied with this assignment.':a.version===2?'Opening cash and owner capital are verified for this episode.':a.topic==='capital'?'Opening cash is $0.':'Opening cash is $8,000, supported by verified owner capital.'} No balances or mistakes carry in from another assignment.</div></div><div class="role-grid"><section class="card">${shop()}<h3>Your mission</h3>${a.version>=2?`<ol class="mission-list">${(a.version===3?a.objectives:a.concepts.map(id=>Lessons.concepts[id].goal)).map(goal=>`<li>${safe(goal)}</li>`).join('')}</ol><p class="foot">Grading: journal 80% · financial report 15% · concept check 5%. Business profit does not determine your grade.</p>`:`<p>${Lessons.topic(a).goal}</p>`}<p>${a.version>=2?'Prepare the journal and the assigned month-end financial report.':Lessons.topic(a).effect}</p></section>${choiceForm(a)}</div>`;
const s=r.scenario,unlocked=Lessons.availableEvents(r),allCorrect=s.events.every(e=>r.entries[e.id]&&Lessons.assess(r.entries[e.id].rows,r.entries[e.id].date,e).correct);return `<button class="quiet" id="back-assignments">← All assignments</button><div class="lesson-heading"><div class="tag">${Lessons.topic(a).name} · ${month(a)}</div><h2>${safe(a.title)}</h2><p>${safe(a.instructions)}</p></div>${a.version>=2?episodeScene(r):''}<div class="episode-strip"><div><span class="tag">YOUR OPERATING PLAN</span>${a.version>=2?`<details><summary>${s.decisions.length} decisions for ${safe(r.business.name)}</summary>${s.decisions.map(x=>`<p>${safe(x)}</p>`).join('')}</details>`:`<strong>${safe(s.decision)}</strong>`}</div><div><span class="tag">VERIFIED STARTING CASH</span><strong>${cash(s.opening)}</strong></div><div><span class="tag">SCENARIO STATUS</span><strong>${r.completed?'Completed':a.version>=2?s.stages[r.stage||0]:r.advanced?'Month-end review':'Business decision made'}</strong></div></div><div class="lesson-workspace"><section class="card"><div class="tag">2 · READ THE BUSINESS RECORDS</div><h2>Records inbox</h2><p>Read dates, payment terms and delivery status. You choose when to do the bookkeeping.</p>${unlocked.map(e=>`<button class="record" data-record="${e.id}"><span>${e.date}<br><strong>${e.title}</strong><small>${r.entries[e.id]?'Entry saved':'Not yet entered'}</small></span><span>View document →</span></button>`).join('')}${a.version>=2?episodeProgress(r):!r.advanced?`<div class="time-step"><h3>${['prepaid','equipment'].includes(a.topic)?'The month moves forward':'The next business event arrives'}</h3><p>${['prepaid','equipment'].includes(a.topic)?'Your business has used its resources for one month. Check what changes at month-end.':'Read the next document to distinguish the later event from the original transaction.'}</p><button id="advance-episode">${['prepaid','equipment'].includes(a.topic)?'Advance to month-end →':'Continue the episode →'}</button></div>`:''}<button class="quiet" id="view-taccounts">Open T accounts</button></section><section class="card bookkeeper"><div class="tag">YOUR BOOKKEEPING</div><h2>${record?'Journal entry':'Open a document to begin'}</h2>${record?journalForm(s.events.find(e=>e.id===record)): '<p>Choose a document in the records inbox. Inspect it before selecting accounts and writing the entry.</p>'}</section></div>${r.advanced?predictionPanel():''}${r.advanced&&r.prediction!==undefined?`<section class="card reflection"><div class="tag">4 · SEE THE FINANCIAL EFFECT</div><h2>What do the accounts tell you?</h2><p>${a.version>=2?'Prepare the journal and the assigned month-end financial report.':Lessons.topic(a).effect} Use your T accounts to reconcile these statement totals.</p><form id="effect-form">${s.effects.map(e=>`<label class="statement-line">${e.label}<input name="${e.key}" aria-label="${e.label}" type="number" step=".01" required value="${safe(r.effectDraft?.[e.key]??'')}"></label>`).join('')}<button ${!allCorrect?'disabled':''}>Check financial effects</button>${!allCorrect?'<p class="foot">Correct the journal entries before completing the statement sections.</p>':''}</form><div id="effect-feedback" role="status">${r.completed?completion(r):''}</div></section>`:''}<section class="card reflection"><h3>Assignment journal</h3><table><thead><tr><th>Date</th><th>Document</th><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody>${Object.entries(r.entries).map(([id,e])=>e.rows.map((x,i)=>`<tr><td>${i===0?e.date:''}</td><td>${i===0?s.events.find(x=>x.id===id).title:''}</td><td>${safe(x.account)}</td><td>${Number(x.debit)?cash(Number(x.debit)):''}</td><td>${Number(x.credit)?cash(Number(x.credit)):''}</td></tr>`).join('')).join('')||'<tr><td colspan="5">Your journal entries will appear here.</td></tr>'}</tbody></table><p class="foot">Corrections replace entries in these books. Original attempts remain in your grading record.</p></section>`;}
function journalForm(e){const r=run(),old=r.entries[e.id];if(record!==r.selectedRecord){entryRows=old?structuredClone(old.rows):[{account:'',debit:'',credit:''},{account:'',debit:'',credit:''}];r.selectedRecord=record;}return `${documentHtml(e,assignment(),r.business)}<form id="journal-form"><label class="field">Journal-entry date<input id="entry-date" type="date" required value="${safe(old?.date||r.entryDateDraft||'')}"></label><table><thead><tr><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody>${entryRows.map((x,i)=>`<tr><td><select data-line="${i}" data-field="account" aria-label="Account ${i+1}" required><option value="">Select account</option>${(assignment().version===3?r.scenario.accountList:assignment().version===2?[...new Set(['Cash','Owner Capital',...r.scenario.events.flatMap(x=>[x.debit,x.credit])])].sort():Lessons.accounts).map(a=>`<option ${a===x.account?'selected':''}>${a}</option>`).join('')}</select></td><td><input data-line="${i}" data-field="debit" aria-label="Debit ${i+1}" type="number" step=".01" min="0" value="${safe(x.debit)}"></td><td><input data-line="${i}" data-field="credit" aria-label="Credit ${i+1}" type="number" step=".01" min="0" value="${safe(x.credit)}"></td></tr>`).join('')}</tbody></table><div class="actions"><button>Save journal entry</button><button type="button" class="secondary" id="add-line">+ Line</button>${assignment().support==='guided'?'<button type="button" class="quiet" id="hint">Concept hint</button>':''}</div></form><div id="entry-feedback" role="status">${old?entryFeedback(Lessons.assess(old.rows,old.date,e)):''}</div>`;}
function entryFeedback(g){return `<div class="message ${g.correct?'':'error'}">${g.correct?'Entry verified. Read your T accounts to see its effect.':`${!g.date?'Check the transaction date. ':''}${!g.account?'Reconsider what the business received, used, earned, or owes. ':!g.amount?'Recheck the amount and which side each account belongs on. ':''}Your first attempt is retained; you can revise this entry.`}</div>`;}
function predictionPanel(){const r=run(),p=r.scenario.prediction;return `<section class="card reflection"><div class="tag">3 · A QUICK CONCEPT CHECK</div><h3>${p.prompt}</h3>${r.prediction===undefined?`<form id="prediction-form">${p.options.map((x,i)=>`<label class="prediction-option"><input type="radio" name="prediction" value="${i}" required>${x}</label>`).join('')}<button>Check my prediction</button></form>`:`<div class="message">${r.prediction===p.correct?'You predicted it correctly.':'Let’s connect the event to the accounts.'} ${p.feedback}</div>`}</section>`;}
function completion(r){const s=Lessons.grade(r);return `<div class="message"><strong>Assignment completed.</strong> First-attempt score: ${s.journal+s.effects+s.prediction}/100. Journal ${s.journal}/80 · effects ${s.effects}/15 · prediction ${s.prediction}/5.<br>Your business identity continues. The next assignment starts with its own balances.</div>`;}
function wireAssignment(){Q('#back-assignments').onclick=()=>{active=null;record=null;notice='';render();};const a=assignment(),r=run();if(!r){const form=Q('#business-choice');const preview=()=>{const choice=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]));const s=Lessons.expected(a,choice,data.profile);Q('#choice-preview').innerHTML=a.version===3?`<strong>Your chosen plan</strong><p>${safe(s.decision)}</p><p>Starting cash: ${cash(s.opening)} · ${s.events.length} documents. Review the facts before preparing the entries.</p>`:a.version===2?`<strong>Your plan, in numbers</strong>${s.decisions.map((x,i)=>`<p>${safe(x)}<br><small>${safe(choiceCostLine(a.concepts[i],s))}</small></p>`).join('')}<p>Verified starting cash: ${cash(s.opening)} · ${s.events.length} source records. Journal entries remain your work.</p>`:`${safe(s.decision)}. Starting cash: ${cash(s.opening)}. The decision creates source documents; you must determine the entries.`;};form.querySelectorAll('select,input').forEach(s=>s.onchange=preview);preview();form.onsubmit=e=>{e.preventDefault();const choice=Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,Number(v)]));data.runs[a.id]={assignment:structuredClone(a),business:structuredClone(data.profile),choice,scenario:Lessons.expected(a,choice,data.profile),entries:{},first:{},advanced:false,completed:false};persist();render();};return;}
document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>viewRecord(b.dataset.record));Q('#view-taccounts').onclick=tAccounts;if(Q('#advance-episode'))Q('#advance-episode').onclick=()=>{if(a.version>=2){r.stage=Math.min(2,(r.stage||0)+1);r.advanced=r.stage===2;}else r.advanced=true;persist();render();};if(Q('#journal-form')){Q('#entry-date').oninput=e=>r.entryDateDraft=e.target.value;document.querySelectorAll('[data-line]').forEach(el=>el.oninput=()=>entryRows[Number(el.dataset.line)][el.dataset.field]=el.value);Q('#add-line').onclick=()=>{if(entryRows.length<8){entryRows.push({account:'',debit:'',credit:''});render();}};if(Q('#hint'))Q('#hint').onclick=()=>{r.hints||=[];if(!r.hints.includes(record))r.hints.push(record);persist();Q('#entry-feedback').innerHTML='<div class="message">'+safe((a.version===2?Lessons.concepts[conceptForRecord(record)]||Lessons.topic(a):Lessons.topic(a)).goal)+' Ask whether the business has received a future benefit, used a resource, earned revenue, or merely received payment for something already recorded.</div>';};Q('#journal-form').onsubmit=e=>{e.preventDefault();const error=Lessons.validateRows(entryRows,r.scenario.accountList||Lessons.accounts);if(error){Q('#entry-feedback').innerHTML='<div class="message error">'+error+'</div>';return;}const event=r.scenario.events.find(e=>e.id===record),date=Q('#entry-date').value,g=Lessons.assess(entryRows,date,event);r.first[record]??=g;r.entries[record]={rows:structuredClone(entryRows),date};r.entryDateDraft='';r.completed=false;persist();render();};}
if(Q('#prediction-form'))Q('#prediction-form').onsubmit=e=>{e.preventDefault();const n=Number(new FormData(e.target).get('prediction'));r.prediction=n;r.predictionFirst??=n;persist();render();};if(Q('#effect-form')){Q('#effect-form').querySelectorAll('input').forEach(el=>el.oninput=()=>{r.effectDraft||={};r.effectDraft[el.name]=el.value;persist();});Q('#effect-form').onsubmit=e=>{e.preventDefault();const input=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));r.effectsFirst??=input;r.effectsLatest=input;const incorrect=r.scenario.effects.filter(x=>Math.abs(input[x.key]-x.value)>.005);if(!incorrect.length){r.completed=true;persist();Q('#effect-feedback').innerHTML=completion(r);}else{persist();Q('#effect-feedback').innerHTML='<div class="message error">Recheck '+incorrect.map(x=>x.label).join(', ')+'. Your first attempt is retained. Use the T accounts to revise your work.</div>';}};}}
function viewRecord(id){const e=run().scenario.events.find(e=>e.id===id),d=Q('#lesson-dialog');d.innerHTML=documentHtml(e,assignment(),run().business)+'<div class="actions"><button id="work-entry">Work on this entry</button><button class="secondary" id="close-record">Keep running the business</button></div>';d.showModal();Q('#close-record').onclick=()=>d.close();Q('#work-entry').onclick=()=>{d.close();record=id;run().entryDateDraft='';render();Q('.bookkeeper').scrollIntoView({behavior:'smooth',block:'start'});};}
function documentHtml(e,a,business){if(e.kind==='generated')return generatedDocument(e,a,business);if(e.kind==='episode')return episodeDocument(e,a,business);const d=e.detail,kind=e.kind,name=safe(business.name);let title='',issuer='',status='',body='',total=cash(e.amount),label='Total';if(kind==='lease'){title='Commercial rental receipt';issuer='Oak Street Property Management';status='PAID';body=`Tenant: ${name}<br>Location: ${['Quiet side street','Neighborhood main street','Town center'][d.location]}<br>Coverage begins: ${Lessons.day(a,1)}<br>Months paid in advance: ${d.months}<br>Monthly rental rate: ${cash(d.rate)}<br>Payment method: business checking`;label='Payment received';}if(kind==='coverage'){title='Rental coverage schedule';issuer='Oak Street Property Management';status='NO PAYMENT DUE';body=`Tenant: ${name}<br>Period ended: ${e.date}<br>Time occupied this period: 1 month<br>Original prepaid coverage: ${d.months} months<br>Monthly rental rate: ${cash(d.rate)}<br>Current cash charge: $0.00`;label='Coverage used at contract rate';}if(kind==='invoice'){title='Customer invoice';issuer=business.name;status='UNPAID';body=`Bill to: Neighborhood catering customer<br>Services delivered: ${e.date}<br>Order status: completed<br>Invoice total: ${cash(d.sale)}<br>Payment terms: agreed partial settlement later this month<br>Payment received on invoice date: $0.00`;label='Amount due';if(business.type==='Design studio')body=body.replace('catering customer','design client');if(business.type==='Bike repair')body=body.replace('catering customer','repair customer');}if(kind==='remittance'){title='Customer payment confirmation';issuer='Neighborhood Bank';status='RECEIVED';body=`Account holder: ${name}<br>Payment against invoice dated: ${Lessons.day(a,8)}<br>Original invoice: ${cash(d.sale)}<br>Transfer received: ${cash(d.paid)}<br>New services included with this transfer: none`;label='Cash deposited';}if(kind==='equipment'){title='Equipment supplier invoice';issuer='Northside Business Equipment';status='PAID';body=`Customer: ${name}<br>Item: ${safe((equipmentNames[business.type]||equipmentNames['Coffee shop'])[[600,1200,1800].indexOf(d.cost)])}<br>Delivered and placed in service: ${e.date}<br>Payment method: business checking`;label='Invoice total';}if(kind==='asset'){title='Fixed asset register';issuer=business.name+' · Business records';status='MONTH-END';body=`Placed in service: ${Lessons.day(a,1)}<br>Cost: ${cash(d.cost)}<br>Estimated useful life: ${d.life} years<br>Residual value: $0.00<br>Depreciation method: straight-line<br>Convention: full month from placement in service<br>Months used this period: 1`;label='Asset cost';total=cash(d.cost);}if(kind==='deposit'){title='Owner capital deposit slip';issuer='Neighborhood Bank';status='RECEIVED';body=`Account holder: ${name}<br>Depositor: business owner<br>Transfer description: initial business investment<br>Customer services involved: none`;label='Cash deposited';}if(kind==='advertising'){title='Advertising service invoice';issuer='Local Reach Media';status='PAID';body=`Client: ${name}<br>Campaign: ${['Local listing','Neighborhood promotion','Opening campaign'][[60,120,200].indexOf(d.ad)]}<br>Service delivered during: ${month(a)}<br>Payment method: business checking`;label='Invoice total';}return `<article class="source-document"><div class="paper-top"><span>${safe(issuer)}</span><span class="paper-status">${status}</span></div><h2>${title}</h2><div class="paper-meta"><span>Document ${safe(e.id).toUpperCase()}</span><span>${e.date}</span></div><div class="paper-item">${safe(e.title)}</div><p>${body}</p><div class="paper-total"><span>${label}</span><strong>${total}</strong></div><div class="paper-footer">Business copy · Retain with assignment records</div></article>`;}
function tAccounts(){const r=run(),b=Lessons.balances(r.scenario,r.entries),d=Q('#lesson-dialog');const used=(r.scenario.accountList||Lessons.accounts).filter(a=>b[a]||Object.values(r.entries).some(e=>e.rows.some(x=>x.account===a)));d.innerHTML='<h2>Assignment T accounts</h2><p>Verified opening balances are included. These books show your latest entries, including errors until corrected.</p><div class="t-grid">'+used.map(a=>{const opening=r.scenario.openingBalances?r.scenario.openingBalances.filter(x=>x.account===a).reduce((n,x)=>n+x.debit-x.credit,0):a==='Cash'?r.scenario.opening:a==='Owner Capital'?-r.scenario.opening:0;return `<section class="t-account"><h3>${a}</h3><div class="t-head"><span>Debit</span><span>Credit</span></div><div class="t-body">${['debit','credit'].map(side=>`<div>${opening&&((opening>0)===(side==='debit'))?`<div><small>Verified opening balance</small>${cash(Math.abs(opening))}</div>`:''}${Object.values(r.entries).flatMap(e=>e.rows.filter(x=>x.account===a&&Number(x[side])).map(x=>`<div><small>${e.date}</small>${cash(Number(x[side]))}</div>`)).join('')}</div>`).join('')}</div><p>Balance: ${cash(Math.abs(b[a]))} ${b[a]>=0?'Dr':'Cr'}</p></section>`;}).join('')+'</div><button id="close-ledger" class="secondary">Back to assignment</button>';d.showModal();Q('#close-ledger').onclick=()=>d.close();}
function defaultDraft(){return {version:1,id:crypto.randomUUID(),topic:'prepaid',title:'',course:'Introduction to Financial Accounting',instructions:'',year:2026,month:9,support:'guided',notes:'',published:false,origin:'Professor assignment'};}
function renderProfessor(){teacherDraft||=data.teacherDraft||defaultDraft();const a=teacherDraft;shell(`<div class="intro"><div><div class="tag">PROFESSOR ASSIGNMENT STUDIO</div><h1>Assignment studio</h1><p>Create a business assignment from your course material. Review the documents and expected accounting before publishing.</p></div><button id="new-draft" class="secondary">New assignment</button></div><nav class="tabs"><button data-teacher="builder" class="${teacherTab==='builder'?'selected':''}">Build assignment</button><button data-teacher="library" class="${teacherTab==='library'?'selected':''}">Published assignments</button></nav>${teacherTab==='library'?teacherLibrary():`<div class="professor-layout"><section class="card"><div class="tag">1 · COURSE MATERIAL</div><h2>Start with your topic or notes</h2><p>Upload your course material. The generator identifies concepts and combines them into a new business episode, with choices, dated records, month-end work, and a verified answer key.</p><label class="field">Upload course notes<input id="notes-file" type="file" accept=".txt,.md,.pdf,.docx,text/plain,text/markdown,application/pdf"></label><label class="field">Or paste notes<textarea id="teacher-notes" maxlength="30000" placeholder="e.g. Prepaid rent is an asset until the coverage is used. At month-end…">${safe(a.notes)}</textarea></label><button id="suggest-topic" class="secondary">Draft from notes</button><p class="foot">Files stay in your browser. Supported: PDF, DOCX, TXT, and Markdown. Scanned PDFs need selectable text or pasted notes. Notes are analyzed in your browser; course material is not sent to an external AI service.</p><div id="notes-analysis">${notesAnalysisHtml(a)}</div><label class="field">Episode length<select id="episode-depth">${[['focused','Focused · fewer operating transactions'],['standard','Standard · a fuller operating month'],['extended','Extended · extra activity to distinguish']].map(([value,label])=>`<option value="${value}" ${(a.depth||'standard')===value?'selected':''}>${label}</option>`).join('')}</select></label></section><section class="card"><div class="tag">2 · ASSIGNMENT SETTINGS</div><h2>Define the lesson</h2><form id="teacher-form"><div class="message">${a.version===3?a.objectives.map(safe).join('<br>'):a.version===2?a.concepts.map(id=>safe(Lessons.concepts[id].name)).join(' · '):'Generate an episode from your notes to set the learning scope.'}</div><label class="field">Assignment title<input name="title" maxlength="160" placeholder="Created from your notes" required value="${safe(a.title)}"></label><label class="field">Course<input name="course" maxlength="120" required value="${safe(a.course)}"></label><label class="field">Financial reporting<select name="report"><option value="topic" ${(a.report||'topic')==='topic'?'selected':''}>Topic balances · focused on the lesson</option><option value="statements" ${a.report==='statements'?'selected':''}>Income statement & balance sheet totals</option></select></label><label class="field">Student instructions<textarea name="instructions" maxlength="10000" placeholder="The student brief appears after you generate the assignment." required>${safe(a.instructions)}</textarea></label><div class="form-pair"><label class="field">Scenario year<input name="year" type="number" min="2020" max="2100" required value="${a.year}"></label><label class="field">Scenario month<select name="month">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${a.month===i+1?'selected':''}>${new Date(2026,i,1).toLocaleDateString('en-US',{month:'long'})}</option>`).join('')}</select></label></div><label class="field">Student support<select name="support"><option value="guided" ${a.support==='guided'?'selected':''}>Guided · concept hints available</option><option value="independent" ${a.support==='independent'?'selected':''}>Independent · no hints</option></select></label><button>Review assignment draft →</button></form></section></div>`}`);Q('#new-draft').onclick=()=>{teacherDraft=defaultDraft();data.teacherDraft=teacherDraft;teacherTab='builder';persist();render();};document.querySelectorAll('[data-teacher]').forEach(b=>b.onclick=()=>{teacherTab=b.dataset.teacher;render();});if(teacherTab==='library'){document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>download('ledger-lane-assignment.json',data.assignments.find(a=>a.id===b.dataset.download)));document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{teacherDraft=structuredClone(data.assignments.find(a=>a.id===b.dataset.review));reviewDraft();});return;}
Q('#notes-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{notice='Reading '+file.name+'…';Q('#notes-analysis').textContent=notice;const text=await readCourseNotes(file);if(text.trim().length<20)throw Error('No readable course text was found. Try a text-based PDF or paste the notes.');if(text.length>30000)throw Error('These notes are long. Upload a chapter or paste the relevant section (up to 30,000 characters).');teacherDraft.notes=text;teacherDraft.needsRegeneration=teacherDraft.version>=2;data.teacherDraft=teacherDraft;notice='Loaded '+file.name+'. Review the concepts, then generate your episode.';persist();render();}catch(error){notice=error.message;render();}};
Q('#teacher-notes').oninput=e=>{teacherDraft.notes=e.target.value;teacherDraft.needsRegeneration=teacherDraft.version>=2;data.teacherDraft=teacherDraft;persist();Q('#notes-analysis').innerHTML=notesAnalysisHtml(teacherDraft);};
Q('#suggest-topic').textContent='Generate a new business episode →';Q('#suggest-topic').onclick=()=>{try{const notes=Q('#teacher-notes').value.trim(),selected=[...document.querySelectorAll('[name=note-concept]:checked')].map(x=>x.value);teacherDraft=Lessons.generateAssignment(notes,{concepts:selected,depth:Q('#episode-depth').value,year:teacherDraft.year,month:teacherDraft.month,course:teacherDraft.course,report:teacherDraft.report});data.teacherDraft=teacherDraft;const s=Lessons.expected(teacherDraft,Lessons.defaultEpisodeChoice(teacherDraft));notice='Generated '+teacherDraft.concepts.length+' decision areas and '+s.events.length+' source records. Review the scope, documents, and answer key before publishing.';persist();render();}catch(error){notice=error.message;render();}};
Q('#teacher-form').querySelectorAll('input,select,textarea').forEach(el=>el.oninput=()=>{teacherDraft[el.name]=['year','month'].includes(el.name)?Number(el.value):el.value;data.teacherDraft=teacherDraft;persist();});Q('#teacher-form').onsubmit=e=>{e.preventDefault();if((teacherDraft.version<2&&!teacherDraft.published)||teacherDraft.needsRegeneration){notice='Generate a fresh episode from these notes first.';render();return;}if(!Lessons.checkAssignment(teacherDraft)){notice='Check the assignment settings before reviewing.';render();return;}reviewDraft();};}
function teacherLibrary(){return `<section class="card"><h2>Assignments ready to share</h2><p>Publish adds an assignment to this browser. Download its file and send it through your LMS; students import it into their business classroom.</p>${data.assignments.map(a=>`<div class="library-row"><div><strong>${safe(a.title)}</strong><p>${Lessons.topic(a).name} · ${month(a)} · ${safe(a.origin)}</p></div><div class="actions"><button class="secondary" data-review="${safe(a.id)}">Review</button><button data-download="${safe(a.id)}">Download assignment</button></div></div>`).join('')}</section>`;}
function defaultChoice(topic){return topic==='prepaid'?{location:1,months:3}:topic==='receivables'?{order:1,collection:1}:topic==='equipment'?{level:1,life:1}:{investment:1,ad:1};}
function reviewDraft(){const a=teacherDraft,s=Lessons.expected(a,a.version===3?{plan:reviewPlan}:a.version===2?Lessons.defaultEpisodeChoice(a):defaultChoice(a.topic)),d=Q('#lesson-dialog'),example={name:'Example Coffee',type:'Coffee shop',color:'sage'};d.innerHTML=`<div class="tag">PROFESSOR REVIEW · DRAFT</div><h2>${safe(a.title)}</h2><p>${safe(a.instructions)}</p>${a.version===3?`<label class="field">Preview operating plan<select id="review-plan">${a.blueprint.paths.map((path,i)=>`<option value="${i}" ${i===reviewPlan?'selected':''}>${safe(path.label)}</option>`).join('')}</select></label>`:''}<div class="message"><strong>Student choice:</strong> ${s.decision}<br>This is a sample choice, not a fixed answer for every student. Amounts and expected entries adapt to each student’s choices.</div>${a.version>=2?`<h3>Course alignment</h3>${notesAnalysisHtml(a,true)}<p>${s.events.length} records · ${a.version===3?'3 alternative operating plans':a.concepts.length+' decision areas'} · three stages · journal and statement totals.</p><p>The preview uses Example Coffee. Each student gets business-specific descriptions and stable, individually varied amounts.</p>`:''}<h3>Sample source documents</h3><div class="review-docs">${s.events.map(e=>documentHtml(e,a,example)).join('')}</div><details class="teacher-key"><summary>Review expected accounting and grading</summary><table><thead><tr><th>Date</th><th>Debit</th><th>Credit</th><th>Amount</th></tr></thead><tbody>${s.events.map(e=>`<tr><td>${e.date}</td><td>${e.lines?e.lines.filter(x=>x.debit).map(x=>safe(x.account)+' '+cash(x.debit)).join('<br>'):e.debit}</td><td>${e.lines?e.lines.filter(x=>x.credit).map(x=>safe(x.account)+' '+cash(x.credit)).join('<br>'):e.credit}</td><td>${cash(e.amount)}</td></tr>`).join('')}</tbody></table><p>${s.prediction.prompt}<br>Expected: ${s.prediction.options[s.prediction.correct]}</p><p>${s.effects.map(e=>e.label+': '+cash(e.value)).join('<br>')}</p><p>Journal 80% · financial effects 15% · prediction 5%. Original attempts retained. Hints have no automatic penalty.</p></details><div class="message">Independent episode. ${a.version===3?'Opening balances: '+a.blueprint.opening.map(x=>safe(x.account)+' '+cash(x.debit||x.credit)+' '+(x.debit?'Dr':'Cr')).join(' · '):s.opening?cash(s.opening)+' verified opening Cash and Owner Capital.':'Starts with no balances.'} No earlier assignment is required.</div><div class="actions"><button id="publish-assignment">${a.published?'Save as a new assignment':'Approve & publish assignment'}</button><button class="secondary" id="close-review">Return to draft</button></div><p class="foot">Professor view is a local prototype, not a secure teacher login. Publishing does not notify students or upload to an LMS.</p>`;d.showModal();if(Q('#review-plan'))Q('#review-plan').onchange=e=>{reviewPlan=Number(e.target.value);d.close();reviewDraft();};Q('#close-review').onclick=()=>d.close();Q('#publish-assignment').onclick=()=>{if(!Lessons.checkAssignment(a))return;const published={...structuredClone(a),id:a.published?crypto.randomUUID():a.id,published:true,origin:'Professor assignment'};data.assignments.push(published);teacherDraft=defaultDraft();data.teacherDraft=teacherDraft;persist();d.close();teacherTab='library';notice='Assignment approved. Download its file to share with students.';render();};}
function download(filename,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importAssignment(){const d=Q('#lesson-dialog');d.innerHTML='<h2>Import your professor’s assignment</h2><p>Select the assignment JSON file your professor shared through your course LMS or email. Your business identity stays the same; the assignment gets fresh accounting records.</p><input id="assignment-file" type="file" accept=".json,application/json"><div id="import-result" role="status"></div><button class="quiet" id="cancel-import">Cancel</button>';d.showModal();Q('#cancel-import').onclick=()=>d.close();Q('#assignment-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>150000)throw Error('Assignment file is too large.');const a=JSON.parse(await file.text());if(!Lessons.checkAssignment(a)||a.published!==true)throw Error('This is not a supported published Ledger Lane assignment.');if(data.assignments.some(x=>x.id===a.id))throw Error('This assignment is already in your classroom.');data.assignments.push({...a,origin:'Professor assignment'});persist();d.close();active=null;notice='Assignment imported. Select it to begin.';render();}catch(err){Q('#import-result').textContent=err.message;}};}
function help(){const d=Q('#lesson-dialog'),teacher=typeof cloudAccount!=='undefined'&&cloudAccount&&cloudAccount.role!=='student';d.innerHTML=`<h2>${teacher?'Instructor guide':'Getting started'}</h2><ol class="instructions">${(teacher?['Create a class in My classroom and approve your students’ email addresses.','Open Assignment studio and upload or paste the course material. Add a short learning goal and choose the period and assignment length.','Create the draft. Review all three business plans, source documents, and expected journal entries. The draft remains private until you publish it.','Publish to the selected class. Students find the assignment in their accounts.','Open the class gradebook to review scores, dated entries, and the original submission history.']:['Create your business, or sign in with the email your professor approved.','Open a class assignment and choose an operating plan.','Read the receipts, invoices, and period-end records. Prepare dated journal entries in your own words through the account lines.','Move the business forward whenever you’re ready. Bookkeeping does not block business activity.','Use the general ledger and source records to complete the assigned financial report. Review feedback and correct your work.']).map(x=>`<li>${x}</li>`).join('')}</ol><p>${teacher?'AI creates a draft, not a published answer. Your review confirms the accounting, source facts, and teaching scope. Generating drafts uses paid API requests; student work and grading do not.':'Each assignment starts with its own balances. Your business identity stays with you; errors in earlier assignments do not carry forward.'}</p><button id="close-help">Close guide</button>`;d.showModal();Q('#close-help').onclick=()=>d.close();}
render();
function episodeChoiceForm(a){return `<section class="card episode-choices"><div class="tag">YOUR PLAN FOR ${safe(month(a)).toUpperCase()}</div><h2>Make the month your own.</h2><p>${a.concepts.length} operating decisions. Each creates its own records. You can run the month before doing any journal entries.</p><form id="business-choice">${Lessons.episodeChoices(a).map((c,i)=>`<fieldset class="decision-block"><legend>${i+1}. ${safe(c.decision)}</legend><p>${safe(c.goal)}</p>${c.fields.map(([field,label,values,numbers])=>`<label class="field">${safe(label)}<select name="${c.id}_${field}">${values.map((x,i)=>`<option value="${numbers?numbers[i]:i}" ${i===1?'selected':''}>${safe(c.id==='equipment'&&field==='level'?equipmentNames[data.profile.type][i]:x)}</option>`).join('')}</select></label>`).join('')}${c.id==='supplies'?`<p class="foot">For your ${safe(data.profile.type.toLowerCase())}: ${safe(Lessons.businesses[data.profile.type].supplies)}. These are operating supplies, not merchandise inventory.</p>`:''}</fieldset>`).join('')}<div class="message" id="choice-preview"></div><button data-cloud-submit>Confirm my operating plan →</button></form></section>`;}
function episodeProgress(r){const stage=r.stage||0,s=r.scenario,total=s.events.length,saved=Object.keys(r.entries).length;return `<div class="episode-progress"><ol>${s.stages.map((x,i)=>`<li class="${i===stage?'current':i<stage?'done':''}"><span>${i+1}</span>${safe(x)}</li>`).join('')}</ol><p>${saved} of ${total} records entered · ${Lessons.availableEvents(r).length} records available</p>${stage<2?`<p>${stage===0?'Your operating plan is in place. Customer activity and service records will arrive next.':'The month’s activity is complete. Gather coverage schedules, counts, and unpaid obligations to close the books.'}</p><button id="advance-episode" data-cloud-submit>${stage===0?'Run the business this month':'Move to month-end'} →</button><small>You can advance with unfinished entries.</small>`:'<div class="message">All records are available. Review the journal, then complete the financial report.</div>'}</div>`;}
function episodeDocument(e,a,business){const lines=e.detail.lines;const moneyKeys=/rate$|premium$|cost|amount|received|principal|payment|due$|wage$|purchased$|at cost$|transfer|advance$|supplies$/i;return `<article class="source-document"><div class="paper-top"><span>${safe(lines.find(([k])=>['Supplier','Provider','Lender','Depositor','Sender'].includes(k))?.[1]||business.name+' · Business records')}</span><span class="paper-status">${e.stage===2?'MONTH-END':'BUSINESS COPY'}</span></div><h2>${safe(e.title)}</h2><div class="paper-meta"><span>Ref ${safe(a.id.slice(0,6)).toUpperCase()}-${safe(e.id).toUpperCase()}</span><span>${safe(e.date)}</span></div><div class="paper-item">${safe(business.name)} · ${safe(business.specialty||business.type)}</div><dl class="document-facts">${lines.map(([key,value])=>`<div><dt>${safe(key)}</dt><dd>${safe(typeof value==='number'&&moneyKeys.test(key)?cash(value):value)}</dd></div>`).join('')}</dl>${e.stage!==2?`<div class="paper-total"><span>Transaction amount</span><strong>${cash(e.amount)}</strong></div>`:''}<div class="paper-footer">Retain with the ${safe(month(a))} business records · All dates refer to this scenario</div></article>`;}
function notesAnalysisHtml(a,review=false){if(a.version===3)return `<div class="scope-analysis"><h3>Learning objectives</h3><ul>${a.objectives.map(x=>`<li>${safe(x)}</li>`).join('')}</ul><h3>Referenced course material</h3>${a.source.map(x=>`<blockquote>${safe(x.evidence)}</blockquote>`).join('')}<p class="foot">Draft reviewed by AI and checked for balanced entries and reporting totals. Confirm source facts, teaching alignment, conventions, and all three plans before publishing.</p></div>`;if(typeof cloudAccount!=='undefined'&&cloudAccount&&!review)return `<p class="foot">${a.notes?.trim()?a.notes.trim().split(/\s+/).length+' words loaded. Generate a new draft after changing the source.':'Upload notes or paste the material you want students to apply.'}</p>`;const analysis=Lessons.analyzeNotes(a.notes||'');return `<div class="scope-analysis"><h3>${analysis.matches.length?'Concepts found in your notes':'What are you teaching?'}</h3>${analysis.matches.length?analysis.matches.map(x=>`<div class="scope-concept">${review?`<strong>${safe(x.name)}</strong>`:`<label><input type="checkbox" name="note-concept" value="${x.id}" ${a.needsRegeneration||!a.concepts||a.concepts.includes(x.id)?'checked':''}> ${safe(x.name)}</label>`}<blockquote>${safe(x.evidence)}</blockquote></div>`).join(''):'<p>Upload or paste the relevant notes. You can combine rent, insurance, supplies, receivables, equipment, owner funding, customer deposits, wages, operating accruals, supplier purchases, loans, withdrawals, and cash revenue.</p>'}${analysis.unsupported.length?`<div class="message error"><strong>Outside the current generator’s scope</strong><p>${analysis.unsupported.map(safe).join('; ')}. These topics will not be assigned or graded. Narrow the source material or leave them for a separate lesson.</p></div>`:''}<p class="foot">Select only concepts already taught. Up to six per episode. Generated depreciation uses straight-line, zero residual value, and a full month; generated loans use simple monthly interest.</p></div>`;}
async function readCourseNotes(file){if(file.size>10*1024*1024)throw Error('Choose a notes file smaller than 10 MB.');if(/\.(txt|md)$/i.test(file.name))return file.text();if(/\.pdf$/i.test(file.name)){const pdfjs=await import('./assets/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdf.worker.mjs',location.href).href;const loadingTask=pdfjs.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false});const pdf=await loadingTask.promise;try{if(pdf.numPages>80)throw Error('Upload the relevant chapter or slides, up to 80 pages.');let text='';for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent();text+=content.items.map(x=>x.str+(x.hasEOL?'\n':' ')).join('')+'\n';if(text.length>30000)break;}return text;}finally{await loadingTask.destroy();}}if(/\.docx$/i.test(file.name)){if(!window.mammoth)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='./assets/mammoth.browser.min.js';script.onload=resolve;script.onerror=()=>reject(Error('The document reader could not load. Refresh or paste your notes.'));document.head.appendChild(script);});const result=await mammoth.extractRawText({arrayBuffer:await file.arrayBuffer()});return result.value;}throw Error('Use PDF, DOCX, TXT, or Markdown. You can also paste text from slides.');}
function conceptForRecord(id){return id.startsWith('rent-')?'prepaid':id.startsWith('insurance-')?'insurance':id.startsWith('supplies-')?'supplies':id.startsWith('customer-')||id==='second-invoice'?'receivables':id.startsWith('equipment-')||id==='asset-register'?'equipment':id==='owner-deposit'||id==='advertising-invoice'?'capital':id.startsWith('booking-')?'unearned':id.startsWith('payroll-')?'wages':id.startsWith('utility-')?'utilities':id.startsWith('supplier-')?'payables':id.startsWith('loan-')||id==='interest-accrual'?'borrowing':id==='owner-withdrawal'?'drawings':'cashsales';}
function choiceCostLine(id,s){const records=s.events.filter(e=>conceptForRecord(e.id)===id),paid=records.filter(e=>e.credit==='Cash').reduce((n,e)=>n+e.amount,0),received=records.filter(e=>e.debit==='Cash').reduce((n,e)=>n+e.amount,0);return [paid?'Planned cash payments: '+cash(paid):'',received?'Planned cash receipts: '+cash(received):'',!paid&&!received?'These records involve an unpaid obligation or a credit transaction.':''].filter(Boolean).join(' · ');}
function episodeScene(r){const stage=r.stage||0,completed=Object.values(data.runs).filter(x=>x.completed).length;return `<section class="episode-scene"><div class="scene-store">${shop(r.business)}</div><div><div class="tag">${safe(month(r.assignment))} AT ${safe(r.business.name).toUpperCase()}</div><h3>${stage===0?'The plan is ready.':stage===1?'Your business is in motion.':'Time to tell the financial story.'}</h3><p>${stage===0?'You have arranged the resources and commitments for this month. Read the first receipts or move ahead to see what happens.':stage===1?'The customer and operating records have arrived. Open each document to find out what was delivered, paid, or still owed.':'The doors are quiet. Coverage schedules, physical counts, and unpaid obligations tell you what belongs in this period.'}</p><span class="scene-badge">${completed?completed+' episodes completed':'Your semester business'} · ${safe(r.business.specialty||r.business.type)}</span></div></section>`;}
function generatedChoiceForm(a){return `<section class="card"><div class="tag">OPERATING DECISION</div><h2>Choose your approach</h2><p>Each plan produces a different set of transactions. Choose how your business will operate, then work from the source records.</p><form id="business-choice">${a.blueprint.paths.map((p,i)=>`<label class="plan-option"><input type="radio" name="plan" value="${i}" ${i===0?'checked':''}><span><strong>${safe(p.label)}</strong><small>${safe(p.description.replaceAll('{{business}}',data.profile.name).replaceAll('{{type}}',data.profile.type))}</small></span></label>`).join('')}<div class="message" id="choice-preview"></div><button data-cloud-submit>Confirm operating plan</button></form></section>`;}
function generatedDocument(e,a,business){const d=e.detail.document;return `<article class="source-document"><div class="paper-top"><span>${safe(d.issuer)}</span><span class="paper-status">${safe(d.status)}</span></div><h2>${safe(e.title)}</h2><div class="paper-meta"><span>Reference ${safe(e.id).toUpperCase()}</span><span>${safe(e.date)}</span></div><div class="paper-item">${safe(business.name)}</div><dl class="document-facts">${d.fields.map(f=>`<div><dt>${safe(f.label)}</dt><dd>${safe(f.value)}</dd></div>`).join('')}</dl><div class="paper-footer">Business copy · ${safe(month(a))}</div></article>`;}
function ledgerPage(){const episodes=Object.entries(data.runs);return `<section class="card"><div class="tag">BUSINESS RECORDS</div><h2>General ledger</h2><p>Review your posted entries in T accounts. Each assignment has separate books and verified starting balances.</p>${episodes.length?`<label class="field">Assignment<select id="ledger-episode">${episodes.map(([id,r])=>`<option value="${safe(id)}">${safe(r.assignment.title)} · ${month(r.assignment)}</option>`).join('')}</select></label><button id="open-ledger">View T accounts</button>`:'<p>Start an assignment to open its ledger.</p>'}</section>`;}
